-- ---------------------------------------------
-- helpers/functions/string_compare.sql
-- ---------------------------------------------
create or alter function mold.string_compare
(
    @a          nvarchar(max),
    @b          nvarchar(max),
    @trim       bit,
    @ignoreCase bit
)
returns smallint
as
begin
    set @a = isnull(@a, N'');
    set @b = isnull(@b, N'');

    if @trim = 1
    begin
        set @a = mold.trim_whitespace(@a);
        set @b = mold.trim_whitespace(@b);
    end

    if @ignoreCase = 1
        return
            case
                when datalength(@a) = datalength(@b)
                 and @a collate Latin1_General_CI_AS
                   = @b collate Latin1_General_CI_AS then 0
                when @a collate Latin1_General_CI_AS
                   < @b collate Latin1_General_CI_AS then -1
                else 1
            end;

    return
        case
            when datalength(@a) = datalength(@b)
             and @a collate Latin1_General_CS_AS
               = @b collate Latin1_General_CS_AS then 0
            when @a collate Latin1_General_CS_AS
               < @b collate Latin1_General_CS_AS then -1
            else 1
        end;
end
go


-- ---------------------------------------------
-- helpers/functions/string_equals.sql
-- ---------------------------------------------
-- =============================================
-- mold.string_equals
-- =============================================
-- Returns 1 if @a and @b are equal under the requested options.
--
-- @trim       1 = trim both values before comparing
-- @ignoreCase 1 = case-insensitive comparison
--             0 = case-sensitive comparison
--
-- Null is treated as the empty string, so string_equals(NULL, '') = 1.
-- That matches the two-value semantics of a string comparison; if a
-- caller needs null to be distinct from '', check @a IS NULL and @b IS
-- NULL before calling.
--
-- Examples:
--   string_equals(N' a ', N'a',   1, 1) -> 1   -- trim + CI
--   string_equals(N'a',   N'A',   0, 1) -> 1
--   string_equals(N'a',   N'A',   0, 0) -> 0
-- =============================================
create or alter function mold.string_equals
(
    @a          nvarchar(max),
    @b          nvarchar(max),
    @trim       bit,
    @ignoreCase bit
)
returns bit
as
begin
    return case
        when mold.string_compare(@a, @b, @trim, @ignoreCase) = 0
            then 1
        else 0
    end;
end
go


