-- ---------------------------------------------
-- helpers/procedures/str_compare.sql
-- ---------------------------------------------

-- =============================================
-- mold.str_compare
-- =============================================
-- Compares two strings using the specified collation.
--
-- @collation  The collation used for comparison.
-- @result     -1 = @a is less than @b
--              0 = @a equals @b
--              1 = @a is greater than @b
--
-- NULL is treated as an empty string.
--
-- Note:
-- SQL Server collation comparison semantics apply.
-- In particular, trailing spaces are ignored during
-- string equality comparisons.
-- =============================================

create or alter procedure mold.str_compare
(
    @a          nvarchar(max),
    @b          nvarchar(max),
    @collation  sysname,
    @result     int output
)
as
begin
    set nocount on;

    set @result = null;

    -- Validate the collation name.
    if @collation is null
       or not exists
       (
           select 1
           from sys.fn_helpcollations()
           where name = @collation
       )
    begin
        throw 50001, 'Invalid collation name.', 1;
    end;

    -- Treat NULL as an empty string.
    set @a = isnull(@a, N'');
    set @b = isnull(@b, N'');

    declare @sql nvarchar(max);

    set @sql =
        N'select @result =
            case
                when @a collate ' + quotename(@collation) + N'
                   = @b collate ' + quotename(@collation) + N' then 0
                when @a collate ' + quotename(@collation) + N'
                   < @b collate ' + quotename(@collation) + N' then -1
                else 1
            end;';

    exec sys.sp_executesql
        @sql,
        N'@a nvarchar(max), @b nvarchar(max), @result int output',
        @a = @a,
        @b = @b,
        @result = @result output;
end
go


-- ---------------------------------------------
-- functions/_normalize_default.sql
-- ---------------------------------------------
-- =============================================
-- mold._normalize_default
-- =============================================
-- Normalizes a default-constraint definition for comparison.
--
--   - trims whitespace
--   - strips wrapping parentheses (repeatedly, up to 10 levels)
--
-- Examples:
--   '((10))'      -> '10'
--   '(getdate())' -> 'getdate()'
--   'N''x'''      -> 'N''x'''
--   NULL          -> NULL
-- =============================================
CREATE OR ALTER FUNCTION mold._normalize_default
(
    @value nvarchar(max)
)
RETURNS nvarchar(max)
AS
BEGIN
    IF @value IS NULL
        RETURN NULL;

    DECLARE @v nvarchar(max) = LTRIM(RTRIM(@value));
    DECLARE @i int = 0;

    -- Strip wrapping parentheses up to 20 levels deep.
    WHILE @i < 20
      AND LEN(@v) >= 2
      AND LEFT(@v, 1) = N'('
      AND RIGHT(@v, 1) = N')'
    BEGIN
        SET @v = LTRIM(RTRIM(SUBSTRING(@v, 2, LEN(@v) - 2)));
        SET @i += 1;
    END

    RETURN @v;
END;
GO

go

-- ---------------------------------------------
-- functions/string_length.sql
-- ---------------------------------------------
CREATE OR ALTER FUNCTION mold._string_length
(
    @system_type_id int,
    @max_length int
)
RETURNS int
AS
BEGIN
    IF @system_type_id IS NULL
        RETURN NULL;

    DECLARE @size int = 0;

    ;WITH string_type_families AS
    (
        SELECT
            system_type_id,
            CASE
                WHEN name IN (N'varchar', N'char', N'varbinary', N'binary')
                    THEN N'bytes'

                WHEN name IN (N'nvarchar', N'nchar')
                    THEN N'unicode'

                WHEN name IN (N'text', N'ntext', N'xml', N'image')
                    THEN N'max'
            END AS size_family
        FROM sys.types
        WHERE user_type_id = system_type_id
          AND is_user_defined = 0
    )
    SELECT @size =
        CASE size_family
            WHEN N'bytes'   THEN @max_length
            WHEN N'unicode' THEN CASE WHEN @max_length = -1 THEN -1 ELSE @max_length / 2 END
            WHEN N'max'     THEN -1
            ELSE 0
        END
    FROM string_type_families
    WHERE system_type_id = @system_type_id;

    RETURN @size;
END;
GO

CREATE OR ALTER FUNCTION mold.string_length
(
    @type sysname,
    @max_length int
)
RETURNS int
AS
BEGIN
    RETURN (
        SELECT mold._string_length(bt.system_type_id, @max_length)
        FROM            sys.types AS rt -- requested type
            INNER JOIN  sys.types AS bt -- base type
                ON bt.user_type_id = rt.system_type_id AND bt.user_type_id = bt.system_type_id
        WHERE rt.user_type_id = TYPE_ID(@type)
    )
END;
GO

go

-- ---------------------------------------------
-- functions/string_max_length.sql
-- ---------------------------------------------
create or alter function mold._string_max_length
(
    @system_type_id int,
    @length int
)
returns int
as
begin
    if @system_type_id is null
        return null;

    declare @max_length int = 0;

    ;with string_type_families as
    (
        select
            system_type_id,
            case
                when name in (N'varchar', N'char', N'varbinary', N'binary')
                    then N'bytes'

                when name in (N'nvarchar', N'nchar')
                    then N'unicode'

                when name in (N'text', N'ntext', N'xml', N'image')
                    then N'max'
            end size_family
        from sys.types
        where user_type_id = system_type_id
            and is_user_defined = 0
    )
    select @max_length =
        case size_family
            when N'bytes'   then @length
            when N'unicode' then case when @length = -1 then -1 else @length * 2 end
            when N'max'     then -1
            else 0
        end
    from string_type_families
    where system_type_id = @system_type_id;

    return @max_length;
end;
go

create or alter function mold.string_max_length
(
    @type sysname,
    @length int
)
returns int
as
begin
    return
    (
        select mold._string_max_length(bt.system_type_id, @length)
        from            sys.types rt -- requested type
            inner join  sys.types bt
                on  bt.user_type_id = rt.system_type_id
                    and bt.user_type_id = bt.system_type_id
        where rt.user_type_id = type_id(@type)
    );
end;
go


-- ---------------------------------------------
-- functions/default_schema.sql
