end
go


-- ---------------------------------------------
-- functions/parse_table_name.sql
-- ---------------------------------------------
create or alter function mold.parse_table_name
(
	@name mold.object_name
)
returns @result table 
(
	[object_id]		int null,
	[db] 			sysname null,
	[schema] 		sysname null,
	[table] 		sysname null,
	[column] 		sysname null,
	[quoted_table]	mold.object_name null,
	[quoted_column]	mold.object_name null
)
as
begin
	if mold.is_null_or_empty(@name) = 1
		return
	
	declare @db sysname
	declare @schema sysname
	declare @table sysname
	declare @column sysname

	declare @part1 sysname
	declare @part2 sysname
	declare @part3 sysname
	declare @part4 sysname

	select
		@part1 = parsename(@name, 4),
		@part2 = parsename(@name, 3),
		@part3 = parsename(@name, 2),
		@part4 = parsename(@name, 1)

	if @part1 is null and @part2 is null and @part3 is null
	begin
		set @table = @part4
	end
	else
	if @part1 is null and @part2 is null
	begin
		set @schema = @part3
		set @table = @part4
	end
	else
	if @part1 is null
	begin
		set @db = @part2
		set @schema = @part3
		set @table = @part4
	end
	else
	begin
		set @db = @part1
		set @schema = @part2
		set @table = @part3
		set @column = @part4
	end

	set @db = mold.resolve_db(@db)
	set @schema = mold.resolve_schema(@db, @schema);

	insert into @result
	(
		[object_id],
		[db],
		[schema],
		[table],
		[column],
		[quoted_table]
	)
	values
	(
		mold.object_id(@db, @schema, @table, N'U'),
		@db,
    	@schema,
		@table,
		@column,
		mold.quote_name(@db, @schema, @table, null)
	)
	
	return
end
go


-- ---------------------------------------------
-- functions/parse_column_type.sql
-- ---------------------------------------------
-- =============================================
-- mold.parse_column_type
-- =============================================
-- Parses a T-SQL type declaration string and returns a single row of
-- normalized metadata describing the type. Intended as the single
-- source of truth for type resolution inside create_column (and any
-- other helper that needs to reason about a column's declared type).
--
-- Accepts (whitespace- and bracket-tolerant):
--   'int'
--   'varchar(100)'
--   'nvarchar(max)'
--   'decimal(18,2)'
--   'datetime2(7)'
--   'uniqueidentifier'
--   '[dbo].[MyUdt]'
--   'varchar(100) NOT NULL'   -- trailing NULL / NOT NULL is stripped
--
-- Returns one row with:
--   input_type, base_type_name, type_schema, type_name, normalized_type,
--   args, arg1, arg2,
--   system_type_id, user_type_id, type_schema_id,
--   is_user_defined, is_table_type, is_assembly_type, collation_name,
--   is_max, char_length, byte_length, precision, scale, fractional_scale,
--   is_valid, validation_error
--
-- Notes:
--   - char_length is in CHARACTERS for nchar/nvarchar and BYTES otherwise.
--   - byte_length matches what sys.columns.max_length would store
--     (-1 for max); use it when comparing against column_info.max_length.
--   - is_valid = 0 when the base type is unknown, arguments are malformed,
--     or the type is a user-defined table type. Callers should THROW
--     using validation_error verbatim.
-- =============================================
CREATE OR ALTER FUNCTION mold.parse_column_type
(
    @type nvarchar(4000)
)
RETURNS TABLE
AS
RETURN
(
    WITH
    src AS
    (
        SELECT
            cleaned = LTRIM(RTRIM(
                          CASE
                              WHEN LTRIM(RTRIM(@type)) LIKE N'% NOT NULL'
                                  THEN LEFT(LTRIM(RTRIM(@type)), LEN(LTRIM(RTRIM(@type))) - 9)
                              WHEN LTRIM(RTRIM(@type)) LIKE N'% NULL'
                                  THEN LEFT(LTRIM(RTRIM(@type)), LEN(LTRIM(RTRIM(@type))) - 5)
                              ELSE LTRIM(RTRIM(@type))
                          END))
    ),
    split AS
    (
        SELECT
            base_name = LTRIM(RTRIM(
                            CASE WHEN CHARINDEX(N'(', s.cleaned) > 0
                                 THEN LEFT(s.cleaned, CHARINDEX(N'(', s.cleaned) - 1)
                                 ELSE s.cleaned END)),
            args      = CASE
                            WHEN CHARINDEX(N'(', s.cleaned) > 0
                                 AND RIGHT(s.cleaned, 1) = N')'
                                THEN SUBSTRING(s.cleaned,
                                               CHARINDEX(N'(', s.cleaned) + 1,
                                               LEN(s.cleaned) - CHARINDEX(N'(', s.cleaned) - 1)
                            ELSE NULL
                        END
        FROM src AS s
    ),
    norm AS
    (
        SELECT
            base_clean  = LTRIM(RTRIM(
                              CASE
                                  WHEN PARSENAME(REPLACE(REPLACE(split.base_name, N'[', N''), N']', N''), 2) IS NOT NULL
                                      THEN PARSENAME(REPLACE(REPLACE(split.base_name, N'[', N''), N']', N''), 1)
                                  ELSE REPLACE(REPLACE(split.base_name, N'[', N''), N']', N'')
                              END)),
            schema_part = CASE
                              WHEN PARSENAME(REPLACE(REPLACE(split.base_name, N'[', N''), N']', N''), 2) IS NOT NULL
                                  THEN PARSENAME(REPLACE(REPLACE(split.base_name, N'[', N''), N']', N''), 2)
                              ELSE NULL
                          END,
            args = split.args
        FROM split
    ),
    argsplit AS
    (
        SELECT
            n.base_clean,
            n.schema_part,
            n.args,
            p1 = CASE
                     WHEN n.args IS NULL THEN NULL
                     WHEN CHARINDEX(N',', n.args) > 0
                         THEN LTRIM(RTRIM(LEFT(n.args, CHARINDEX(N',', n.args) - 1)))
                     ELSE LTRIM(RTRIM(n.args))
                 END,
            p2 = CASE
                     WHEN n.args IS NULL THEN NULL
                     WHEN CHARINDEX(N',', n.args) > 0
                         THEN LTRIM(RTRIM(SUBSTRING(n.args, CHARINDEX(N',', n.args) + 1, 4000)))
                     ELSE NULL
                 END
        FROM norm AS n
    ),
    resolved AS
    (
        SELECT
            a.base_clean,
            a.schema_part,
            a.args,
            a.p1,
            a.p2,
            t.system_type_id,
            t.user_type_id,
            t.name        AS type_name,
            t.schema_id   AS type_schema_id,
            t.is_user_defined,
            t.is_table_type,
            t.is_assembly_type,
            t.max_length,
            t.precision,
            t.scale,
            t.collation_name
        FROM argsplit AS a
        OUTER APPLY
        (
            SELECT TOP (1) *
            FROM sys.types AS t
            WHERE t.name = a.base_clean
              AND (a.schema_part IS NULL OR t.schema_id = SCHEMA_ID(a.schema_part))
            ORDER BY
                t.is_user_defined ASC,
                CASE WHEN a.schema_part IS NOT NULL AND t.schema_id = SCHEMA_ID(a.schema_part) THEN 0 ELSE 1 END,
                CASE WHEN t.schema_id = SCHEMA_ID(N'dbo') THEN 0 ELSE 1 END
        ) AS t
    ),
    interpreted AS
    (
        SELECT
            r.base_clean,
            r.schema_part,
            r.args,
            r.p1,
            r.p2,
            r.system_type_id,
            r.user_type_id,
            r.type_name,
            r.type_schema_id,
            r.is_user_defined,
            r.is_table_type,
            r.is_assembly_type,
            r.collation_name,

            is_max = CASE WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN 1 ELSE 0 END,

                        char_length =
                CASE
                    WHEN r.type_name IN (N'char', N'varchar', N'binary', N'varbinary') THEN
                        CASE
                            WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN -1
                            WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                            ELSE 1                                  -- default length is 1
                        END
                    WHEN r.type_name IN (N'nchar', N'nvarchar') THEN
                        CASE
                            WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN -1
                            WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                            ELSE 1                                  -- default length is 1 char
                        END
                    ELSE NULL
                END,

            num_precision =
                CASE
                    WHEN r.type_name IN (N'decimal', N'numeric') THEN
                        CASE WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                             ELSE r.precision END
                    WHEN r.type_name IN (N'tinyint', N'smallint', N'int', N'bigint',
                                         N'money', N'smallmoney', N'float', N'real',
                                         N'datetime', N'datetime2', N'datetimeoffset',
                                         N'time', N'bit')
                        THEN r.precision
                    ELSE NULL
                END,

            num_scale =
                CASE
                    WHEN r.type_name IN (N'decimal', N'numeric') THEN
                        CASE WHEN r.p2 IS NOT NULL THEN TRY_CAST(r.p2 AS int)
                             WHEN r.p1 IS NOT NULL THEN 0
                             ELSE r.scale END
                    WHEN r.type_name IN (N'datetime2', N'datetimeoffset', N'time') THEN
                        CASE WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                             ELSE r.scale END
                    WHEN r.type_name IN (N'money', N'smallmoney') THEN r.scale
                    ELSE NULL
                END,

            frac_scale =
                CASE
                    WHEN r.type_name IN (N'datetime2', N'datetimeoffset', N'time') THEN
                        CASE WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                             ELSE r.scale END
                    ELSE NULL
                END,

            byte_length =
                CASE
                    WHEN r.type_name IN (N'nchar', N'nvarchar') THEN
                        CASE
                            WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN -1
                            WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int) * 2
                            ELSE 2                                  -- 1 char = 2 bytes
                        END
                    WHEN r.type_name IN (N'char', N'varchar', N'binary', N'varbinary') THEN
                        CASE
                            WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN -1
                            WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                            ELSE 1                                  -- default length is 1 byte
                        END
                    ELSE r.max_length
                END,

            has_unknown_base_type =
                CASE WHEN r.type_name IS NULL THEN 1 ELSE 0 END,

            has_bad_arg =
                CASE
                    WHEN r.args IS NULL THEN 0
                    WHEN r.type_name IN (N'char', N'varchar', N'nchar', N'nvarchar',
                                         N'binary', N'varbinary')
                         AND NOT (LOWER(r.p1) = N'max'
                                  OR (TRY_CAST(r.p1 AS int) IS NOT NULL AND TRY_CAST(r.p1 AS int) > 0))
                        THEN 1
                    WHEN r.type_name IN (N'decimal', N'numeric')
                         AND (TRY_CAST(r.p1 AS int) IS NULL
                              OR TRY_CAST(r.p1 AS int) NOT BETWEEN 1 AND 38
                              OR (r.p2 IS NOT NULL AND (TRY_CAST(r.p2 AS int) IS NULL OR TRY_CAST(r.p2 AS int) < 0))
                              OR (r.p2 IS NOT NULL AND TRY_CAST(r.p2 AS int) > TRY_CAST(r.p1 AS int)))
                        THEN 1
                    WHEN r.type_name IN (N'datetime2', N'datetimeoffset', N'time')
                         AND (TRY_CAST(r.p1 AS int) IS NULL OR TRY_CAST(r.p1 AS int) NOT BETWEEN 0 AND 7)
                        THEN 1
                    WHEN r.type_name NOT IN (N'char', N'varchar', N'nchar', N'nvarchar',
                                             N'binary', N'varbinary',
                                             N'decimal', N'numeric',
                                             N'datetime2', N'datetimeoffset', N'time')
                         AND r.p1 IS NOT NULL
                        THEN 1
                    ELSE 0
                END,

            normalized_type =
                CASE
                    WHEN r.type_name IS NULL THEN NULL

                        WHEN r.type_name IN (N'char', N'varchar', N'binary', N'varbinary') THEN
                            r.type_name + N'('
                            + (CASE
                                WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN N'max'
                                WHEN r.p1 IS NOT NULL THEN r.p1
                                ELSE N'1'
                            END)
                            + N')'

                    WHEN r.type_name IN (N'nchar', N'nvarchar') THEN
                        r.type_name + N'('
                        + (CASE
                               WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN N'max'
                               WHEN r.p1 IS NOT NULL THEN r.p1
                               ELSE N'1'
                           END)
                        + N')'

                    WHEN r.type_name IN (N'decimal', N'numeric') THEN
                        r.type_name + N'('
                        + CAST(ISNULL(TRY_CAST(r.p1 AS int), r.precision) AS nvarchar(20))
                        + N','
                        + CAST(ISNULL(TRY_CAST(r.p2 AS int), 0) AS nvarchar(20))
                        + N')'

                    WHEN r.type_name IN (N'datetime2', N'datetimeoffset', N'time') THEN
                        r.type_name + N'('
                        + CAST(ISNULL(TRY_CAST(r.p1 AS int), r.scale) AS nvarchar(20))
                        + N')'

                    WHEN r.is_user_defined = 1 AND r.schema_part IS NOT NULL THEN
                        QUOTENAME(r.schema_part) + N'.' + QUOTENAME(r.type_name)

                    ELSE r.type_name
                END
        FROM resolved AS r
    )
    SELECT
        input_type         = @type,

        base_type_name     = base_clean,
        type_schema        = schema_part,
        type_name          = type_name,
        normalized_type    = normalized_type,
        args               = args,
        arg1               = p1,
        arg2               = p2,

        system_type_id     = system_type_id,
        user_type_id       = user_type_id,
        type_schema_id     = type_schema_id,
        is_user_defined    = is_user_defined,
        is_table_type      = is_table_type,
        is_assembly_type   = is_assembly_type,
        collation_name     = collation_name,

        is_max             = is_max,
        char_length        = char_length,
        byte_length        = byte_length,
        precision          = num_precision,
        scale              = num_scale,
        fractional_scale   = frac_scale,

        is_valid           = CASE
                                 WHEN has_unknown_base_type = 1 THEN 0
                                 WHEN has_bad_arg = 1 THEN 0
                                 WHEN is_table_type = 1 THEN 0
                                 ELSE 1
                             END,
        validation_error   =
            CASE
                WHEN has_unknown_base_type = 1
                    THEN N'Unknown type name: ' + ISNULL(base_clean, N'(null)')
                WHEN is_table_type = 1
                    THEN N'User-defined table types cannot be used as column types: ' + base_clean
                WHEN has_bad_arg = 1
                    THEN N'Invalid argument(s) for type ' + base_clean + N': (' + ISNULL(args, N'') + N')'
                ELSE NULL
            END
    FROM interpreted
);
go


-- ---------------------------------------------
-- functions/parse_column_name.sql
-- ---------------------------------------------
create or alter function mold.parse_column_name
(
	@name mold.object_name
)
returns @result table 
(
	[object_id]		int null,
	[db] 			sysname null,
	[schema] 		sysname null,
	[table] 		sysname null,
	[column] 		sysname null,
	[quoted_table]	mold.object_name null,
	[quoted_column]	mold.object_name null
)
as
begin
	if mold.is_null_or_empty(@name) = 1
		return
	
	declare @db		sysname
	declare @schema sysname
	declare @table	sysname
	declare @column sysname

	declare @part1 sysname
	declare @part2 sysname
	declare @part3 sysname
	declare @part4 sysname

	select
		@part1 = parsename(@name, 4),
		@part2 = parsename(@name, 3),
		@part3 = parsename(@name, 2),
		@part4 = parsename(@name, 1)

	if @part1 is null and @part2 is null and @part3 is null
	begin
		set @column = @part4
	end
	else
	if @part1 is null and @part2 is null
	begin
		set @table = @part3
		set @column = @part4
	end
	else
	if @part1 is null
	begin
		set @schema = @part2
		set @table = @part3
		set @column = @part4
	end
	else
	begin
		set @db = @part1
		set @schema = @part2
		set @table = @part3
		set @column = @part4
	end

	set @db = mold.resolve_db(@db)
	set @schema = mold.resolve_schema(@db, @schema);

	insert into @result
	(
		[object_id],
		[db],
		[schema],
		[table],
		[column],
		[quoted_table],
		[quoted_column]
	)
	values
	(
		mold.object_id(@db, @schema, @table, N'U'),
		@db,
    	@schema,
		@table,
		@column,
		mold.quote_name(@db, @schema, @table, null),
		mold.quote_name(@db, @schema, @table, @column)
	)

	return
end

go


-- ---------------------------------------------
-- functions/parse_column_list.sql
-- ---------------------------------------------
-- =============================================
-- mold.parse_column_list
-- =============================================
CREATE OR ALTER FUNCTION mold.parse_column_list
(
    @name nvarchar(2000)
)
RETURNS TABLE
AS
RETURN
    WITH
        parsed AS
        (
            SELECT
                ends_with_rparen =
                    CASE
                        WHEN LEN(@name) >= 1 AND RIGHT(@name, 1) = N')' THEN 1
                        ELSE 0
                    END
        ),
        nums AS
        (
            SELECT TOP (LEN(@name))
                n = ROW_NUMBER() OVER (ORDER BY (SELECT NULL))
            FROM sys.all_objects a CROSS JOIN sys.all_objects b
        ),
        positions AS
        (
            SELECT
                n = nums.n,
                ch = SUBSTRING(@name, nums.n, 1)
            FROM nums
        ),
        depth_calc AS
        (
            SELECT
                n, ch,
                depth = SUM(
                    CASE
                        WHEN ch = N']' THEN 1
                        WHEN ch = N'[' THEN -1
                        ELSE 0
                    END
                ) OVER (ORDER BY n ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING)
            FROM positions
        ),
        matching_open AS
        (
            SELECT TOP (1) n AS open_pos
            FROM depth_calc
            WHERE ch = N'('
                AND ISNULL(depth, 0) = 0
                AND (SELECT ends_with_rparen FROM parsed) = 1
            ORDER BY n DESC
        ),
        parts AS
        (
            SELECT
                table_part =
                    CASE
                        WHEN (SELECT open_pos FROM matching_open) IS NOT NULL THEN
                            mold.trim_right(
                                LEFT(@name, (SELECT open_pos FROM matching_open) - 1),
                                N'.', 0)
                        ELSE @name
                    END,
                column_part =
                    CASE
                        WHEN (SELECT open_pos FROM matching_open) IS NOT NULL THEN
                            SUBSTRING(@name,
                                (SELECT open_pos FROM matching_open) + 1,
                                LEN(@name) - (SELECT open_pos FROM matching_open) - 1)
                        ELSE NULL
                    END
            FROM parsed
        ),
        tbl AS
        (
            SELECT
                pt.[object_id],
                pt.[db],
                pt.[schema],
                pt.[table],
                pp.column_part
            FROM parts pp
            CROSS APPLY mold.parse_table_name(pp.table_part) pt
        )
    -- Branch 1: multi-column form.
    SELECT
        [object_id] = t.object_id,
        [db]        = t.[db],
        [schema]    = t.[schema],
        [table]     = t.[table],
        [column]    = LTRIM(RTRIM(j.[value])),
        [ord]       = j.[key] + 1
    FROM tbl t
    CROSS APPLY OPENJSON(
        N'[' + ISNULL(
            N'"' + REPLACE(REPLACE(t.column_part, N'"', N'""'), N',', N'","') + N'"',
            N'null'
        ) + N']'
    ) j
    WHERE t.column_part IS NOT NULL

    UNION ALL

    -- Branch 2: single-column form.
    SELECT
        [object_id] = pc.[object_id],
        [db]        = pc.[db],
        [schema]    = pc.[schema],
        [table]     = pc.[table],
        [column]    = pc.[column],
        [ord]       = 1
    FROM mold.parse_column_name(@name) pc
    WHERE NOT EXISTS (SELECT 1 FROM parts WHERE column_part IS NOT NULL)
        AND pc.[column] IS NOT NULL;
GO

go

-- ---------------------------------------------
-- functions/default_exists.sql
-- ---------------------------------------------
-- =============================================
-- mold.default_exists
-- =============================================
-- Returns 1 if the column has a default constraint (optionally matching
-- a specific value), 0 otherwise.
--
-- Accepts a column reference in these forms:
--   'Products.IsShipped'                -> dbo.Products.IsShipped
--   'sales.Products.IsShipped'          -> sales.Products.IsShipped
--   'db.sales.Products.IsShipped'       -> db.sales.Products.IsShipped
--   '[sales].[My.Table].[IsShipped]'    -> sales.[My.Table].[IsShipped]
--
-- If @expected_value is NULL, only the presence of the default is checked.
-- If @expected_value is provided, the default definition is normalized
-- (via _normalize_default) and compared to the normalized expected value.
-- =============================================
CREATE OR ALTER FUNCTION mold.default_exists
(
    @name           mold.object_name,
    @expected_value nvarchar(max) = NULL
)
RETURNS bit
AS
BEGIN
    DECLARE @existing_default nvarchar(max)

    SET @existing_default = mold.column_default(@name)

    IF @existing_default IS NULL
        RETURN 0;

    -- Presence-only check.
    IF @expected_value IS NULL
        RETURN 1;

    -- Value check.
    DECLARE @actual_norm   nvarchar(max) = mold._normalize_default(@existing_default);
    DECLARE @expected_norm nvarchar(max) = mold._normalize_default(@expected_value);

    RETURN CASE WHEN @actual_norm = @expected_norm THEN 1 ELSE 0 END;
END;
GO

go

-- ---------------------------------------------
-- functions/foreign_key_exists.sql
-- ---------------------------------------------
-- =============================================
-- mold.foreign_key_exists
-- =============================================
CREATE OR ALTER FUNCTION mold.foreign_key_exists
(
    @fk_column nvarchar(2000),
    @pk_column nvarchar(2000)
)
RETURNS bit
AS
BEGIN
    IF      mold.is_empty(@fk_column) = 1
        OR  mold.is_empty(@pk_column) = 1
        RETURN 0;

    DECLARE @fk TABLE
    (
        [object_id] int,
        [db]        sysname,
        [schema]    sysname,
        [table]     sysname,
        [column]    sysname,
        [ord]       int
    );

    DECLARE @pk TABLE
    (
        [object_id] int,
        [db]        sysname,
        [schema]    sysname,
        [table]     sysname,
        [column]    sysname,
        [ord]       int
    );

    INSERT INTO @fk ([object_id], [db], [schema], [table], [column], ord)
    SELECT [object_id], [db], [schema], [table], [column], [ord]
    FROM mold.parse_column_list(@fk_column);

    INSERT INTO @pk ([object_id], [db], [schema], [table], [column], ord)
    SELECT [object_id], [db], [schema], [table], [column], [ord]
    FROM mold.parse_column_list(@pk_column);

    IF NOT EXISTS (SELECT 1 FROM @fk) OR NOT EXISTS (SELECT 1 FROM @pk)
        RETURN 0;

    DECLARE @fk_count int = (SELECT COUNT(*) FROM @fk);
    DECLARE @pk_count int = (SELECT COUNT(*) FROM @pk);

    IF @fk_count <> @pk_count
        RETURN 0;

    DECLARE @fk_table_id int, @fk_db sysname, @fk_schema sysname, @fk_table sysname;
    DECLARE @pk_table_id int, @pk_db sysname, @pk_schema sysname, @pk_table sysname;

    SELECT TOP (1)
        @fk_table_id = [object_id], @fk_db = [db], @fk_schema = [schema], @fk_table = [table]
    FROM @fk;

    SELECT TOP (1)
        @pk_table_id = [object_id], @pk_db = [db], @pk_schema = [schema], @pk_table = [table]
    FROM @pk;

    DECLARE @current_db sysname = DB_NAME()

    IF @fk_db <> @current_db or @pk_db <> @current_db
        RETURN 0;

    IF @fk_table_id IS NULL OR @pk_table_id IS NULL
        RETURN 0;

    RETURN CASE
        WHEN EXISTS 
        (
            SELECT 1
            FROM            sys.foreign_key_columns fkc
                INNER JOIN  sys.foreign_keys        fk      ON fk.object_id     = fkc.constraint_object_id
                INNER JOIN  sys.columns             fk_col  ON fk_col.object_id = fkc.parent_object_id      AND fk_col.column_id = fkc.parent_column_id
                INNER JOIN  sys.columns             pk_col  ON pk_col.object_id = fkc.referenced_object_id  AND pk_col.column_id = fkc.referenced_column_id
                INNER JOIN  @fk                     f       ON f.ord            = fkc.constraint_column_id  AND f.[column] = fk_col.name
                INNER JOIN  @pk                     p       ON p.ord            = fkc.constraint_column_id  AND p.[column] = pk_col.name
            WHERE fkc.parent_object_id = @fk_table_id AND fkc.referenced_object_id = @pk_table_id
            GROUP BY fk.object_id
            HAVING COUNT(*) = @fk_count
        ) THEN 1
        ELSE 0
    END;
END;
GO

go

-- ---------------------------------------------
-- functions/primary_key_exists.sql
-- ---------------------------------------------
/*
    Function: primary_key_exists

    Description:
        Determines whether the specified table has a primary key whose
        complete column list matches the supplied columns in the same order.

    Input:
        @name - A table-and-column specification accepted by parse_column_list.
                Examples:
                    N'dbo.Users.Id'
                    N'dbo.UserRoles(UserId,RoleId)'

    Returns:
        bit
            1 - The table's primary key contains exactly the supplied columns,
                in the supplied order.
            0 - The table does not exist, has no primary key, the supplied
                columns do not exactly match its primary key, the input is
                invalid, or the specification refers to another database.

    Notes:
        - Uses parse_column_list to parse the input.
        - Checks metadata in the current database only. A scalar UDF cannot
          use dynamic SQL to inspect an arbitrary database.
        - Composite-key column order is significant.
        - A partial or superset column list is not considered a match.
*/

CREATE OR ALTER FUNCTION mold.primary_key_exists
(
    @name nvarchar(1000)
)
RETURNS bit
AS
BEGIN
    IF mold.is_empty(@name) = 1
        RETURN 0;

    DECLARE
        @db             sysname,
        @schema         sysname,
        @table          sysname,
        @object_id      int,
        @column_count   int;

    DECLARE @columns TABLE
    (
        [object_id] int,
        [db]        sysname,
        [schema]    sysname,
        [table]     sysname,
        [column]    sysname,
        [ord]       int
    );

    INSERT INTO @columns
    (
        [object_id],
        [db],
        [schema],
        [table],
        [column],
        [ord]
    )
    SELECT
        [object_id],
        [db],
        [schema],
        [table],
        [column],
        [ord]
    FROM mold.parse_column_list(@name);

    SELECT TOP (1)
        @object_id  = [object_id],
        @db         = [db],
        @schema     = [schema],
        @table      = [table]
    FROM @columns;

    SELECT @column_count = COUNT(*) FROM @columns;

    -- A valid specification must identify a database, schema, table,
    -- and at least one column.
    IF @column_count = 0 OR @db IS NULL OR @schema IS NULL OR @table IS NULL
        RETURN 0;

    -- Scalar UDFs cannot use dynamic SQL to inspect another database.
    IF @db <> DB_NAME()
        RETURN 0;

    IF @object_id IS NULL
        RETURN 0;

    /*
        Match a primary-key constraint only when:
          1. Its number of key columns equals the requested column count.
          2. Every requested column matches the key column at the same
             ordinal position.

        The second condition uses a double NOT EXISTS so that every
        requested column must have a corresponding key column.
    */
    IF EXISTS
    (
        SELECT 1
        FROM sys.key_constraints kc
        WHERE kc.parent_object_id = @object_id
          AND kc.type = N'PK'
          AND
          (
              SELECT COUNT(*)
              FROM sys.index_columns ic
              WHERE ic.object_id = kc.parent_object_id
                AND ic.index_id = kc.unique_index_id
                AND ic.key_ordinal > 0
          ) = @column_count
          AND NOT EXISTS
          (
              SELECT 1
              FROM @columns requested
              WHERE NOT EXISTS
              (
                  SELECT 1
                  FROM sys.index_columns ic
                  INNER JOIN sys.columns c
                      ON c.object_id = ic.object_id
                     AND c.column_id = ic.column_id
                  WHERE ic.object_id = kc.parent_object_id
                    AND ic.index_id = kc.unique_index_id
                    AND ic.key_ordinal = requested.[ord]
                    AND c.name = requested.[column]
              )
          )
    )
        RETURN 1;

    RETURN 0;
END
GO

go

-- ---------------------------------------------
-- functions/column_default.sql
-- ---------------------------------------------
-- =============================================
-- mold.column_default
-- =============================================
-- Returns the default-constraint definition for a column, or NULL if
-- the column has no default constraint (or the table/column does not
-- exist).
--
-- The returned value is the raw definition from sys.default_constraints
-- (e.g. '((0))', '(getdate())', 'N''hello'''). Use default_exists if you
-- want to compare against an expected value; that function normalizes
-- both sides via _normalize_default.
--
-- Input formats:
--   'Products.IsShipped'                -> dbo.Products.IsShipped
--   'sales.Products.IsShipped'          -> sales.Products.IsShipped
--   'db.sales.Products.IsShipped'       -> db.sales.Products.IsShipped
--   '[sales].[My.Table].[IsShipped]'    -> sales.[My.Table].[IsShipped]
-- =============================================
CREATE OR ALTER FUNCTION mold.column_default
(
    @column mold.object_name
)
RETURNS nvarchar(max)
AS
BEGIN
    DECLARE @object_id  int
    DECLARE @default_value nvarchar(max)

    SELECT
        @object_id = [object_id],
        @default_value = [default_value]
    FROM mold.column_info(@column);

    IF @object_id IS NULL
        RETURN NULL;

    RETURN @default_value;
END;
GO

go

-- ---------------------------------------------
-- functions/column_info.sql
-- ---------------------------------------------
set ansi_nulls on
go

set quoted_identifier on
go

drop function if exists mold.column_info;
go
-- =============================================
-- mold.column_info
-- =============================================
-- Returns one row per column with detailed information,
-- or an empty result set if the specified column or table does not exist.
--
-- Input formats:
--   'Table.Column'                  -> dbo.Table.Column
--   'Schema.Table.Column'           -> Schema.Table.Column
--   'Db.Schema.Table.Column'        -> Db.Schema.Table.Column
--   '[sales].[My.Table].[My.Column]'-> sales.[My.Table].[My.Column]
--
-- Notes:
--   - max_length is the raw sys.columns value, in bytes; -1 means (max).
--   - length is the character count for nchar/nvarchar, the byte count
--     for char/varchar/binary/varbinary, and -1 for (max). It is
--     determined from system_type_id so UDTs based on those types are
--     handled correctly.
--   - is_xml is 1 for the xml system type; is_xml_document is the
--     separate flag from sys.columns that constrains the xml to document
--     form.
--   - default_value is normalized via _normalize_default; default_name
--     is the raw constraint name.
--   - parent_column contains the comma-separated list of distinct,
--     fully qualified referenced columns when this column participates
--     in one or more outgoing foreign keys; NULL otherwise.
--     For composite FKs, each child column maps to its corresponding
--     referenced column.
--   - parent_column is populated only for the child (referencing) side
--     of an FK. To find columns referencing this column, query
--     column_foreign_keys() or sys.foreign_key_columns.
--   - is_primary_key is 1 when the column is part of the primary key.
--   - primary_key_constraint is the name of the primary key constraint
--     when the column participates in the PK, NULL otherwise.
--   - is_primary_key is 1 when the column is part of the primary key.
--   - parent_column is NULL for the parent (referenced) side of an FK;
--     to find "who references me", query sys.foreign_key_columns with
--     referenced_object_id / referenced_column_id instead.
--   - primary_key_constraint is the name of the primary key constraint
--     when the column participates in the PK, NULL otherwise.
--   - parent_column and foreign_key_constraint are both NULL for the
--     referenced (parent) side of an FK; the join reports the child side.
--   - Returned table
-- @result table
-- (
--     [object_id]               int,
--     [db]                      sysname,
--     [schema_name]             sysname,
--     [table_name]              sysname,
--     [column_name]             sysname,
--     [column_id]               int,
--     [type_name]               sysname,
--     [type_schema_id]          int,
--     [type_schema_name]        sysname,
--     [user_type_id]            int,
--     [system_type_id]          int,
--     [max_length]              int,
--     [length]                  int,
--     [precision]               int,
--     [scale]                   int,
--     [collation_name]          sysname,
--     [is_nullable]             bit,
--     [is_identity]             bit,
--     [is_computed]             bit,
--     [is_persisted]            bit,
--     [is_sparse]               bit,
--     [is_filestream]           bit,
--     [is_xml]                  bit,
--     [is_xml_document]         bit,
--     [is_rowguidcol]           bit,
--     [default_value]           nvarchar(max),
--     [default_name]            sysname,
--     [computed_definition]     nvarchar(max),
--     [column_description]      nvarchar(max),
--     [parent_column]           nvarchar(max),   -- fully qualified parent column(s) when column participates in an FK, else NULL
--     [is_primary_key]          bit,              -- 1 when the column participates in the PK, else 0
--     [primary_key_constraint]  sysname,   -- name of the PK constraint, NULL if not in the PK
-- )
-- =============================================
create or alter function mold.column_info
(
    @column mold.object_name
)
returns table
as
return
(
    with parsed as
    (
        select
            [object_id], [db], [schema], [table], [column]
        from mold.parse_column_name(@column)
        where [column] is not null

        union all

        select
            [object_id], [db], [schema], [table], [column]
        from mold.parse_table_name(@column)
        where [column] is null
    )
    select
        [object_id]                       = p.[object_id],
        [db]                              = p.[db],
        [schema_name]                     = p.[schema],
        [table_name]                      = p.[table],
        [column_name]                     = c.name,
        [column_id]                       = c.column_id,
        [type_name]                       = t.name,
        [type_schema_id]                  = t.schema_id,
        [type_schema_name]                = schema_name(t.schema_id),
        [user_type_id]                    = c.user_type_id,
        [system_type_id]                  = c.system_type_id,
        [has_user_defined_type]           = t.is_user_defined,
        [has_assembly_type]               = t.is_assembly_type,
        [max_length]                      = c.max_length,
        [length]                          = mold._string_length(c.system_type_id, c.max_length),
        [precision]                       = c.[precision],
        [scale]                           = c.scale,
        [collation_name]                  = c.collation_name,
        [is_nullable]                     = c.is_nullable,
        [is_identity]                     = c.is_identity,
        [is_computed]                     = c.is_computed,
        [is_persisted]                    = isnull(cc.is_persisted, 0),
        [is_sparse]                       = c.is_sparse,
        [is_filestream]                   = c.is_filestream,
        [is_xml]                          = case when c.system_type_id = 241 then 1 else 0 end,
        [is_xml_document]                 = c.is_xml_document,
        [xml_schema_collection_id]        = nullif(c.xml_collection_id, 0),
        [xml_schema_collection_name]      = xsc.name,
        [xml_schema_collection_schema_id] = xsc.schema_id,
        [xml_schema_collection_schema_name] = schema_name(xsc.schema_id),
        [is_rowguidcol]                   = c.is_rowguidcol,
        [default_value]                   = mold._normalize_default(dc.definition),
        [default_name]                    = dc.name,
        [computed_definition]             = cc.definition,
        [column_description]              = cast(ep.value as nvarchar(max)),
        [parent_column]                   = fk.parent_column,
        [is_primary_key]                  = case when pk.column_id is not null then 1 else 0 end,
        [primary_key_constraint]          = pk.pk_name
    from            parsed                      p
        inner join  sys.columns                 c    on  c.object_id = p.object_id
                                                            and (c.name = p.[column] or p.[column] is null)
        inner join  sys.types                   t    on  t.user_type_id = c.user_type_id
        left join   sys.xml_schema_collections  xsc  on  xsc.xml_collection_id = c.xml_collection_id
        left join   sys.default_constraints     dc   on  dc.parent_object_id = c.object_id
                                                            and dc.parent_column_id = c.column_id
        left join   sys.computed_columns        cc   on  cc.object_id = c.object_id
                                                            and cc.column_id = c.column_id
        left join   sys.extended_properties     ep   on  ep.major_id = c.object_id
                                                            and ep.minor_id = c.column_id
                                                            and ep.name = N'MS_Description'
                                                            and ep.class = 1
        left join
        (
            select
                ic.object_id, ic.column_id, i.name pk_name
            from            sys.index_columns ic
                inner join  sys.indexes       i on i.object_id = ic.object_id and i.index_id = ic.index_id
            where i.is_primary_key = 1
        ) pk on  pk.object_id = c.object_id and pk.column_id = c.column_id
        outer apply
        (
            select
                parent_column = stuff
                (
                    (
                        select
                            N', ' + pc.parent_column
                        from
                        (
                            select distinct
                                parent_column =
                                    quotename(object_schema_name(fkc.referenced_object_id))
                                    + N'.' + quotename(object_name(fkc.referenced_object_id))
                                    + N'.' + quotename(rc.name)
                            from            sys.foreign_key_columns fkc
                                inner join  sys.columns             rc
                                    on  rc.object_id = fkc.referenced_object_id
                                            and rc.column_id = fkc.referenced_column_id
                            where fkc.parent_object_id = c.object_id
                                and fkc.parent_column_id = c.column_id
                        ) pc
                        order by pc.parent_column
                        for xml path(''), type
                    ).value('.', 'nvarchar(max)'),
                    1,
                    2,
                    N''
                )
        ) fk
    where p.object_id is not null
        and p.[db] = db_name()
);
go


-- ---------------------------------------------
-- functions/column_foreign_keys.sql
-- ---------------------------------------------

create or alter function mold.column_foreign_keys
(
    @column mold.object_name,
    @dir varchar(8)
)
returns table
as
return
(
    with parsed as
    (
        select
            [object_id], [db], [schema], [table], [column]
        from mold.parse_column_name(@column)
        where [column] is not null

        union all

        select
            [object_id], [db], [schema], [table], [column]
        from mold.parse_table_name(@column)
        where [column] is null
    ),
    target_columns as
    (
        select
            c.object_id,
            c.column_id
        from            parsed      p
            inner join  sys.columns c   on  c.object_id = p.object_id
                                            and (c.name = p.[column] or p.[column] is null)
        where p.object_id is not null
            and p.[db] = db_name()
    )
    select
        direction               = cast('outgoing' as varchar(8)),
        constraint_name         = fk.name,

        child_schema            = object_schema_name(fk.parent_object_id),
        child_table             = object_name(fk.parent_object_id),
        child_column            = pc.name,

        parent_schema           = object_schema_name(fk.referenced_object_id),
        parent_table            = object_name(fk.referenced_object_id),
        parent_column           = rc.name,

        constraint_column_id    = fkc.constraint_column_id,
        is_disabled             = fk.is_disabled,
        is_not_trusted          = fk.is_not_trusted,
        delete_rule             = fk.delete_referential_action_desc,
        update_rule             = fk.update_referential_action_desc
    from            target_columns          tc
        inner join  sys.foreign_key_columns fkc on  fkc.parent_object_id = tc.object_id
                                                    and fkc.parent_column_id = tc.column_id
        inner join  sys.foreign_keys        fk  on  fk.object_id = fkc.constraint_object_id
        inner join  sys.columns             pc  on  pc.object_id = fkc.parent_object_id
                                                    and pc.column_id = fkc.parent_column_id
        inner join  sys.columns             rc  on  rc.object_id = fkc.referenced_object_id
                                                    and rc.column_id = fkc.referenced_column_id
    where @dir is null or @dir = '' or @dir in ('out', 'outgoing')

    union all

    select
        direction               = cast('incoming' as varchar(8)),
        constraint_name         = fk.name,

        child_schema            = object_schema_name(fk.parent_object_id),
        child_table             = object_name(fk.parent_object_id),
        child_column            = pc.name,

        parent_schema           = object_schema_name(fk.referenced_object_id),
        parent_table            = object_name(fk.referenced_object_id),
        parent_column           = rc.name,

        constraint_column_id    = fkc.constraint_column_id,
        is_disabled             = fk.is_disabled,
        is_not_trusted          = fk.is_not_trusted,
        delete_rule             = fk.delete_referential_action_desc,
        update_rule             = fk.update_referential_action_desc
    from            target_columns          tc
        inner join  sys.foreign_key_columns fkc on  fkc.referenced_object_id = tc.object_id
                                                    and fkc.referenced_column_id = tc.column_id
        inner join  sys.foreign_keys        fk  on  fk.object_id = fkc.constraint_object_id
        inner join  sys.columns             pc  on  pc.object_id = fkc.parent_object_id
                                                    and pc.column_id = fkc.parent_column_id
        inner join  sys.columns             rc  on  rc.object_id = fkc.referenced_object_id
                                                    and rc.column_id = fkc.referenced_column_id
    where @dir is null or @dir = '' or @dir in ('in', 'incoming')
);
go


-- ---------------------------------------------
-- functions/column_api.sql
-- ---------------------------------------------
-- =============================================
-- Column property functions (scalar)
-- =============================================
-- These are thin wrappers over mold.column_info to make it easy
-- to check a single property of a column.
--
-- All take a single argument: a column reference
--   ('Table.Column', 'Schema.Table.Column', 'Db.Schema.Table.Column', ...).
--
-- If the column does not exist, they return NULL (for most) or 0 (for
-- boolean checks).
-- =============================================


-- ---------------------------------------------
-- Boolean checks (return bit)
-- ---------------------------------------------

CREATE OR ALTER FUNCTION mold.is_nullable(@column mold.object_name)
RETURNS bit
AS
BEGIN
    RETURN (select is_nullable FROM mold.column_info(@column));
END;
GO

CREATE OR ALTER FUNCTION mold.is_identity(@column mold.object_name)
RETURNS bit
AS
BEGIN
    RETURN (select is_identity FROM mold.column_info(@column));
END;
GO

CREATE OR ALTER FUNCTION mold.is_sparse(@column mold.object_name)
RETURNS bit
AS
BEGIN
    RETURN (select is_sparse FROM mold.column_info(@column));
END;
GO

CREATE OR ALTER FUNCTION mold.is_computed(@column mold.object_name)
RETURNS bit
AS
BEGIN
    RETURN (select is_computed FROM mold.column_info(@column));
END;
GO

CREATE OR ALTER FUNCTION mold.is_filestream(@column mold.object_name)
RETURNS bit
AS
BEGIN
    RETURN (select is_filestream FROM mold.column_info(@column));
END;
GO

CREATE OR ALTER FUNCTION mold.is_xml(@column mold.object_name)
RETURNS bit
AS
BEGIN
    RETURN (select is_xml FROM mold.column_info(@column));
END;
GO

CREATE OR ALTER FUNCTION mold.is_rowguidcol(@column mold.object_name)
RETURNS bit
AS
BEGIN
    RETURN (select is_rowguidcol FROM mold.column_info(@column));
END;
GO


-- ---------------------------------------------
-- String / scalar properties
-- ---------------------------------------------

CREATE OR ALTER FUNCTION mold.column_typename(@column mold.object_name)
RETURNS sysname
AS
BEGIN
    RETURN (select type_name FROM mold.column_info(@column));
END;
GO


create or alter function mold.column_type
(
    @column mold.object_name
)
returns nvarchar(517)
as
begin
    declare @type_name sysname;
    declare @length int;
    declare @max_length int;
    declare @precision tinyint;
    declare @scale tinyint;
    declare @has_user_defined_type bit;
    declare @type_length nvarchar(35);
    declare @type_schema_name sysname;
    declare @xml_schema_collection_id int;
    declare @xml_schema_collection_name sysname;
    declare @xml_schema_collection_schema_name sysname;
    declare @is_xml_document bit;

    select
        @type_name = type_name,
        @length = length,
        @precision = precision,
        @scale = scale,
        @has_user_defined_type = has_user_defined_type,
        @type_schema_name = type_schema_name,
        @xml_schema_collection_id = xml_schema_collection_id,
        @xml_schema_collection_name = xml_schema_collection_name,
        @xml_schema_collection_schema_name = xml_schema_collection_schema_name,
        @is_xml_document = is_xml_document
    from mold.column_info(@column);

    if @type_name is null
        return null;

    if @has_user_defined_type = 1
        return quotename(@type_schema_name) + N'.' + quotename(@type_name);

    if @type_name = N'xml'
    begin
        if @xml_schema_collection_id is null
            return N'xml';

        return
            N'xml('
            + case when @is_xml_document = 1 then N'DOCUMENT ' else N'CONTENT ' end
            + quotename(@xml_schema_collection_schema_name)
            + N'.'
            + quotename(@xml_schema_collection_name)
            + N')';
    end;

    if @type_name in (N'char', N'varchar', N'nchar', N'nvarchar', N'binary', N'varbinary')
    begin
        set @max_length = mold.string_max_length(@type_name, @length);

        if @max_length = -1
            set @type_length = N'(max)';
        else
            set @type_length = N'(' + convert(nvarchar(10), @max_length) + N')';

        return @type_name + @type_length;
    end;

    if @type_name in (N'decimal', N'numeric')
        return @type_name
            + N'(' + convert(nvarchar(3), @precision)
            + N',' + convert(nvarchar(3), @scale) + N')';

    if @type_name in (N'time', N'datetime2', N'datetimeoffset', N'float')
        return @type_name
            + N'(' + convert(nvarchar(3),
                case
                    when @type_name = N'float' then @precision
                    else @scale
                end
            ) + N')';

    return @type_name;
end;
go

CREATE OR ALTER FUNCTION mold.column_collation(@column mold.object_name)
RETURNS sysname
AS
BEGIN
    RETURN (select collation_name FROM mold.column_info(@column));
END;
GO

