-- ---------------------------------------------
-- functions/table_summary.sql
-- ---------------------------------------------
CREATE OR ALTER FUNCTION mold.table_summary
(
    @name mold.object_name
)
RETURNS TABLE
AS
RETURN
(
    SELECT ci.*
    FROM mold.column_summary(@name) AS ci
